/* Fast portfolio calculations implemented as a NumPy C extension. */
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>

static PyObject *portfolio_risk_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights, *cov;
    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights,
                          &PyArray_Type, &cov))
        return NULL;

    if (PyArray_NDIM(weights) != 1 || PyArray_NDIM(cov) != 2) {
        PyErr_SetString(PyExc_ValueError, "weights must be 1D and cov_matrix must be 2D");
        return NULL;
    }
    npy_intp n = PyArray_DIM(weights, 0);
    if (PyArray_DIM(cov, 0) != n || PyArray_DIM(cov, 1) != n) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix must be square and match weights");
        return NULL;
    }
    if (PyArray_TYPE(weights) != NPY_DOUBLE || PyArray_TYPE(cov) != NPY_DOUBLE ||
        !PyArray_IS_C_CONTIGUOUS(weights) || !PyArray_IS_C_CONTIGUOUS(cov)) {
        PyErr_SetString(PyExc_TypeError, "arrays must be contiguous float64 arrays");
        return NULL;
    }

    const double *x = (const double *)PyArray_DATA(weights);
    const double *s = (const double *)PyArray_DATA(cov);
    double result = 0.0;
    /* Keep the same row-major accumulation order as the Python baseline. */
    for (npy_intp i = 0; i < n; ++i) {
        const double *row = s + i * n;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j)
            row_sum += row[j] * x[j];
        result += x[i] * row_sum;
    }
    return PyFloat_FromDouble(sqrt(result));
}

static PyObject *portfolio_return_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights, *returns;
    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights,
                          &PyArray_Type, &returns))
        return NULL;
    if (PyArray_NDIM(weights) != 1 || PyArray_NDIM(returns) != 1 ||
        PyArray_DIM(weights, 0) != PyArray_DIM(returns, 0)) {
        PyErr_SetString(PyExc_ValueError, "weights and expected_returns must be matching 1D arrays");
        return NULL;
    }
    if (PyArray_TYPE(weights) != NPY_DOUBLE || PyArray_TYPE(returns) != NPY_DOUBLE ||
        !PyArray_IS_C_CONTIGUOUS(weights) || !PyArray_IS_C_CONTIGUOUS(returns)) {
        PyErr_SetString(PyExc_TypeError, "arrays must be contiguous float64 arrays");
        return NULL;
    }
    npy_intp n = PyArray_DIM(weights, 0);
    const double *x = (const double *)PyArray_DATA(weights);
    const double *r = (const double *)PyArray_DATA(returns);
    double result = 0.0;
    for (npy_intp i = 0; i < n; ++i)
        result += x[i] * r[i];
    return PyFloat_FromDouble(result);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Compute sqrt(x^T S x)."},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Compute x^T r."},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
